%%{
    machine simple;

    @LANG: ruby

    main := 'hello' @{ puts "Hello World!" };
}%%
"""

lexer = guess_lexer(ragel_ruby_code)
print(f"Expected: RagelRubyLexer, Got: {lexer.__class__.__name__}")

